// Calculate date range for the past week
const now = new Date();

// Find last Friday at 5pm (or fallback to 7 days ago)
const dayOfWeek = now.getDay();
let daysSinceFriday = (dayOfWeek + 2) % 7;
if (daysSinceFriday === 0 && now.getHours() < 17) {
  daysSinceFriday = 7;
}

const endDate = new Date(now);
endDate.setHours(23, 59, 59, 999);

const startDate = new Date(endDate);
startDate.setDate(endDate.getDate() - 7);
startDate.setHours(0, 0, 0, 0);

const since = startDate.toISOString();
const until = endDate.toISOString();

// Format human-readable date range
const options = { year: 'numeric', month: 'long', day: 'numeric' };
const dateRange = `${startDate.toLocaleDateString('en-US', options)} - ${endDate.toLocaleDateString('en-US', options)}`;

return {
  since,
  until,
  dateRange,
  weekLabel: `Week of ${startDate.toLocaleDateString('en-US', { month: 'long', day: 'numeric' })}`
};

// Merge and format GitHub data for the Claude prompt
const commits = $input.all().filter(i => i.json && i.json.sha).map(i => ({
  type: 'commit',
  sha: i.json.sha?.substring(0, 7),
  message: i.json.commit?.message?.split('\n')[0] || 'No message',
  author: i.json.commit?.author?.name || i.json.author?.login || 'Unknown',
  date: i.json.commit?.author?.date || i.json.created_at
}));

const issues = $input.all().filter(i => i.json && i.json.html_url && !i.json.pull_request).map(i => ({
  type: 'issue',
  number: i.json.number,
  title: i.json.title,
  state: i.json.state,
  url: i.json.html_url,
  labels: (i.json.labels || []).map(l => l.name),
  closed_at: i.json.closed_at
}));

const prs = $input.all().filter(i => i.json && i.json.html_url && i.json.pull_request || (i.json.merged_at)).map(i => ({
  type: 'pr',
  number: i.json.number,
  title: i.json.title,
  merged: !!i.json.merged_at,
  url: i.json.html_url,
  author: i.json.user?.login,
  merged_at: i.json.merged_at
}));

const config = $('Configuration').item.json;
const dates = $('Calculate Week Dates').item.json;

return {
  config,
  dates,
  commits,
  issues,
  prs,
  commitCount: commits.length,
  issueCount: issues.length,
  prCount: prs.length
};

// Build the Claude prompt based on language
const data = $input.first().json;
const lang = data.config.language || 'EN';
const dates = data.dates;

const prompts = {
  EN: `You are a technical project manager writing a weekly development summary.

Based on the following GitHub activity for the repository **${data.config.githubOwner}/${data.config.githubRepo}**, write a clear, concise narrative summary of what the team accomplished this week (${dates.dateRange}).

## Activity Data

### Commits (${data.commitCount})
${data.commits.map(c => `- [​${c.sha}​] ${c.message} — ${c.author} (${c.date?.substring(0, 10)})`).join('\n') || 'No commits this week.'}

### Closed Issues (${data.issueCount})
${data.issues.map(i => `- #${i.number}: ${i.title} [${(i.labels || []).join(', ') || 'no labels'}]`).join('\n') || 'No issues closed this week.'}

### Merged PRs (${data.prCount})
${data.prs.map(p => `- #${p.number}: ${p.title} by ${p.author}${p.merged ? ' ✅ merged' : ''}`).join('\n') || 'No PRs merged this week.'}

## Instructions

Write a summary with these sections:
1. **Overview** — One-paragraph high-level summary of the week
2. **Key Accomplishments** — 3-5 bullet points of the most important things shipped
3. **By the Numbers** — Quick stats (commits, issues closed, PRs merged)
4. **What's Next** — Brief look ahead based on what's in progress

Keep it professional but engaging. Use emoji sparingly. Target ~300-400 words.`,

  FR: `Vous êtes un chef de projet technique qui rédige un résumé hebdomadaire de développement.

Sur la base de l'activité GitHub suivante pour le dépôt **${data.config.githubOwner}/${data.config.githubRepo}**, rédigez un résumé narratif clair et concis de ce que l'équipe a accompli cette semaine (${dates.dateRange}).

## Données d'activité

### Commits (${data.commitCount})
${data.commits.map(c => `- [​${c.sha}​] ${c.message} — ${c.author} (${c.date?.substring(0, 10)})`).join('\n') || 'Aucun commit cette semaine.'}

### Issues fermées (${data.issueCount})
${data.issues.map(i => `- #${i.number}: ${i.title} [${(i.labels || []).join(', ') || 'aucun label'}]`).join('\n') || 'Aucune issue fermée cette semaine.'}

### PRs fusionnées (${data.prCount})
${data.prs.map(p => `- #${p.number}: ${p.title} par ${p.author}${p.merged ? ' ✅ fusionnée' : ''}`).join('\n') || 'Aucune PR fusionnée cette semaine.'}

## Instructions

Rédigez un résumé avec ces sections :
1. **Aperçu** — Résumé de haut niveau en un paragraphe
2. **Réalisations clés** — 3-5 points sur les choses les plus importantes livrées
3. **En chiffres** — Statistiques rapides (commits, issues fermées, PRs fusionnées)
4. **Prochaines étapes** — Bref aperçu de ce qui est en cours

Restez professionnel mais engageant. Utilisez les emoji avec parcimonie. Visez environ 300-400 mots.`
};

const prompt = prompts[lang] || prompts['EN'];

return {
  prompt,
  lang,
  repo: `${data.config.githubOwner}/${data.config.githubRepo}`,
  weekLabel: dates.weekLabel
};

