// Extract summary text from Claude response and add metadata
const claudeResponse = $input.first().json;
const promptData = $('Build Claude Prompt').item.json;

// Claude returns content array with text blocks
const summaryText = claudeResponse.content?.[0]?.text || 'No summary generated.';

const header = promptData.lang === 'FR'
  ? `📋 **Résumé de développement hebdomadaire** — ${promptData.weekLabel}\n📦 Dépôt : ${promptData.repo}\n\n`
  : `📋 **Weekly Development Summary** — ${promptData.weekLabel}\n📦 Repository: ${promptData.repo}\n\n`;

return {
  fullSummary: header + summaryText,
  summary: summaryText,
  header,
  repo: promptData.repo,
  weekLabel: promptData.weekLabel,
  lang: promptData.lang,
  usage: claudeResponse.usage || {}
};

